using System;using System.Windows.Controls;
partial class TerminalWindow {
 TextBlock proxyHealthStatus;
 public void ShowProxyPage(){memoTab="网络与代理";ShowPage("侦探备忘录");}
 void BuildProxyHealthSettings(Panel body,MonitorConfig cfg){SettingsLabel(body,"网络与代理 · 后台侦察");MonitorToggle(body,"网络与代理提醒总开关",()=>assistant.Config.NetworkAlerts,v=>assistant.Config.NetworkAlerts=v);MonitorToggle(body,"允许查询公网出口（ipwho.is）",()=>cfg.ExitLookupEnabled,v=>cfg.ExitLookupEnabled=v);MonitorToggle(body,"代理超时或无法连接时提醒",()=>cfg.ProxyTimeoutAlerts,v=>cfg.ProxyTimeoutAlerts=v);SettingDescription(body,"开启出口查询和代理提醒后，即使详情卡片关闭也会后台检测。通过现有代理通道访问 ipwho.is，服务会收到公网出口IP和常规HTTPS信息，不发送文件或通知。不发送模型请求。默认每60秒检查，连续2次超时或无法连接后提醒，同类故障每5分钟最多提醒一次；声音、动作、气泡与全屏静音沿用提醒方式设置。检测服务故障不会直接断言VPN掉线；直连/TUN模式不据此判断HTTP代理超时。");proxyHealthStatus=Text(assistant.ProxyHealth.Status,13);body.Children.Add(proxyHealthStatus);var interval=TaskbarRange(body,"检查间隔（秒）",cfg.ProxyCheckSeconds,15,300);var failures=TaskbarRange(body,"连续失败次数",cfg.ProxyFailureCount,1,5);var cooldown=TaskbarRange(body,"重复提醒间隔（秒）",cfg.ProxyCooldownSeconds,30,3600);Button(body,"保存代理提醒设置",()=>{int i=TaskbarInt(interval),f=TaskbarInt(failures),c=TaskbarInt(cooldown);if(i<15||i>300||f<1||f>5||c<30||c>3600)throw new ArgumentException("检查间隔15–300秒，连续失败1–5次，重复提醒30–3600秒。");SaveMonitor(()=>{cfg.ProxyCheckSeconds=i;cfg.ProxyFailureCount=f;cfg.ProxyCooldownSeconds=c;});});BuildExitConnection(body,cfg);}
}
